    """Detect the field delimiter. Most US bank exports use commas, but
    some European bank exports (and Excel's regional CSV export) use
    semicolons or tabs instead. Without this, those files silently parse
    to zero transactions instead of raising a clear error."""
    sample = csv_text[:4096]
    try:
        return csv.Sniffer().sniff(sample, delimiters=",;\t").delimiter
    except csv.Error:
        return ","


